BEGIN;
CREATE TABLE IF NOT EXISTS gestao_grupo_filial(id BIGSERIAL PRIMARY KEY,nome VARCHAR(120) NOT NULL,descricao TEXT,ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP NOT NULL DEFAULT NOW(),atualizado_em TIMESTAMP);
CREATE TABLE IF NOT EXISTS gestao_grupo_filial_item(id BIGSERIAL PRIMARY KEY,grupo_filial_id BIGINT NOT NULL REFERENCES gestao_grupo_filial(id),estab_oracle INTEGER NOT NULL,nome_filial VARCHAR(180),ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP NOT NULL DEFAULT NOW(),atualizado_em TIMESTAMP,UNIQUE(grupo_filial_id,estab_oracle));
CREATE TABLE IF NOT EXISTS gestao_fluxo_classificacao(id BIGSERIAL PRIMARY KEY,nome VARCHAR(120) NOT NULL,origem VARCHAR(40) NOT NULL,tipo_especial VARCHAR(60) NOT NULL CHECK(tipo_especial IN('NORMAL','PROVISAO','ADIANTAMENTO_CLIENTE','ADIANTAMENTO_FORNECEDOR','EMPRESTIMO_INTERLOJAS','PREVISAO_INTELIGENTE')),estab_oracle INTEGER,idsituacao_oracle INTEGER,idanalitica_oracle INTEGER,idpess_oracle INTEGER,texto_contem VARCHAR(180),ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP NOT NULL DEFAULT NOW(),atualizado_em TIMESTAMP);
CREATE TABLE IF NOT EXISTS gestao_fluxo_finalizador_mapa(id BIGSERIAL PRIMARY KEY,tipo_finalizador VARCHAR(40) NOT NULL CHECK(tipo_finalizador IN('DINHEIRO','PIX','CARTAO_DEBITO')),codigo_oracle VARCHAR(80),descricao_oracle VARCHAR(180),ativo BOOLEAN NOT NULL DEFAULT TRUE,criado_em TIMESTAMP NOT NULL DEFAULT NOW(),atualizado_em TIMESTAMP);
CREATE TABLE IF NOT EXISTS gestao_fonte_dados(id BIGSERIAL PRIMARY KEY,nome VARCHAR(120) NOT NULL UNIQUE,descricao TEXT,categoria VARCHAR(80),banco_origem VARCHAR(40) NOT NULL,tipo VARCHAR(40) NOT NULL,sql_texto TEXT NOT NULL,parametros_json JSONB NOT NULL DEFAULT '{}',ativo BOOLEAN NOT NULL DEFAULT TRUE,editavel BOOLEAN NOT NULL DEFAULT TRUE,criado_por BIGINT,atualizado_por BIGINT,publicado_por BIGINT,criado_em TIMESTAMP NOT NULL DEFAULT NOW(),atualizado_em TIMESTAMP,publicado_em TIMESTAMP);
CREATE TABLE IF NOT EXISTS gestao_fonte_dados_versao(id BIGSERIAL PRIMARY KEY,fonte_dados_id BIGINT NOT NULL REFERENCES gestao_fonte_dados(id),versao INTEGER NOT NULL,sql_texto TEXT NOT NULL,parametros_json JSONB,alterado_por BIGINT,alterado_em TIMESTAMP NOT NULL DEFAULT NOW(),observacao TEXT,UNIQUE(fonte_dados_id,versao));
CREATE TABLE IF NOT EXISTS gestao_fonte_dados_log(id BIGSERIAL PRIMARY KEY,fonte_dados_id BIGINT REFERENCES gestao_fonte_dados(id),usuario_id BIGINT,parametros_json JSONB,tempo_ms INTEGER,quantidade_linhas INTEGER,sucesso BOOLEAN NOT NULL,erro TEXT,executado_em TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS gestao_fluxo_processo(id BIGSERIAL PRIMARY KEY,usuario_id BIGINT,escopo VARCHAR(40) NOT NULL,estab_oracle INTEGER,grupo_filial_id BIGINT REFERENCES gestao_grupo_filial(id),data_inicial DATE NOT NULL,data_final DATE NOT NULL,saldo_conciliado BOOLEAN NOT NULL DEFAULT FALSE,mostra_provisao BOOLEAN NOT NULL DEFAULT FALSE,mostra_adiantamento BOOLEAN NOT NULL DEFAULT FALSE,mostra_emprestimo BOOLEAN NOT NULL DEFAULT FALSE,usa_previsao_inteligente BOOLEAN NOT NULL DEFAULT TRUE,parametros_json JSONB,status VARCHAR(40) NOT NULL DEFAULT 'PROCESSANDO',mensagem TEXT,criado_em TIMESTAMP NOT NULL DEFAULT NOW(),concluido_em TIMESTAMP);
CREATE TABLE IF NOT EXISTS gestao_fluxo_dia(id BIGSERIAL PRIMARY KEY,processo_id BIGINT NOT NULL REFERENCES gestao_fluxo_processo(id) ON DELETE CASCADE,estab_oracle INTEGER,data_fluxo DATE NOT NULL,disponivel_inicial NUMERIC(18,2),entradas_previstas NUMERIC(18,2),entradas_realizadas NUMERIC(18,2),saidas_previstas NUMERIC(18,2),saidas_realizadas NUMERIC(18,2),receitas_financeiras NUMERIC(18,2) DEFAULT 0,pagamentos_fornecedores NUMERIC(18,2) DEFAULT 0,pagamentos_despesas NUMERIC(18,2) DEFAULT 0,investimentos NUMERIC(18,2) DEFAULT 0,amortizacao_emprestimos NUMERIC(18,2) DEFAULT 0,provisoes NUMERIC(18,2) DEFAULT 0,adiantamentos NUMERIC(18,2) DEFAULT 0,emprestimos_interlojas NUMERIC(18,2) DEFAULT 0,previsao_dinheiro NUMERIC(18,2),previsao_pix NUMERIC(18,2),previsao_cartao_debito NUMERIC(18,2),previsao_inteligente NUMERIC(18,2),movimento_liquido NUMERIC(18,2),saldo_projetado NUMERIC(18,2),status_caixa VARCHAR(30),criado_em TIMESTAMP NOT NULL DEFAULT NOW(),UNIQUE(processo_id,estab_oracle,data_fluxo));
CREATE TABLE IF NOT EXISTS gestao_fluxo_detalhe(id BIGSERIAL PRIMARY KEY,processo_id BIGINT NOT NULL REFERENCES gestao_fluxo_processo(id) ON DELETE CASCADE,estab_oracle INTEGER,data_fluxo DATE NOT NULL,tipo_movimento VARCHAR(30),grupo_movimento VARCHAR(80),tipo_especial VARCHAR(80),origem_movimento VARCHAR(60),id_documento_oracle VARCHAR(80),documento VARCHAR(120),id_portador_oracle INTEGER,portador VARCHAR(180),id_pessoa_oracle INTEGER,pessoa VARCHAR(250),id_situacao_oracle INTEGER,situacao VARCHAR(180),id_analitica_oracle INTEGER,analitica VARCHAR(250),data_emissao DATE,data_vencimento DATE,valor_original NUMERIC(18,2),valor_entrada NUMERIC(18,2),valor_saida NUMERIC(18,2),valor_liquido NUMERIC(18,2),vencido_antes_periodo BOOLEAN NOT NULL DEFAULT FALSE,historico TEXT,dados_origem_json JSONB,criado_em TIMESTAMP NOT NULL DEFAULT NOW());
CREATE TABLE IF NOT EXISTS gestao_fluxo_insight(id BIGSERIAL PRIMARY KEY,processo_id BIGINT NOT NULL REFERENCES gestao_fluxo_processo(id) ON DELETE CASCADE,tipo VARCHAR(40) NOT NULL,severidade VARCHAR(40) NOT NULL,titulo VARCHAR(180) NOT NULL,descricao TEXT NOT NULL,data_referencia DATE,valor_referencia NUMERIC(18,2),filtro_json JSONB,criado_em TIMESTAMP NOT NULL DEFAULT NOW());
CREATE INDEX IF NOT EXISTS idx_gestao_fluxo_dia_01 ON gestao_fluxo_dia(processo_id,data_fluxo); CREATE INDEX IF NOT EXISTS idx_gestao_fluxo_detalhe_01 ON gestao_fluxo_detalhe(processo_id,data_fluxo); CREATE INDEX IF NOT EXISTS idx_gestao_fluxo_detalhe_02 ON gestao_fluxo_detalhe(processo_id,tipo_movimento,grupo_movimento,tipo_especial); CREATE INDEX IF NOT EXISTS idx_gestao_fluxo_insight_01 ON gestao_fluxo_insight(processo_id,severidade); CREATE INDEX IF NOT EXISTS idx_gestao_fonte_dados_01 ON gestao_fonte_dados(categoria,banco_origem,ativo);
INSERT INTO modulos(codigo,nome,descricao,icone,ordem) VALUES('GESTAO','Control S Gestão','Gestão financeira e operacional','ChartNoAxesCombined',20) ON CONFLICT(codigo) DO UPDATE SET ativo=TRUE;
INSERT INTO menus(modulo_id,codigo,nome,rota,icone,ordem) SELECT id,'GESTAO_FLUXO_CAIXA','Fluxo de Caixa','/gestao/fluxo-caixa','CalendarDays',1 FROM modulos WHERE codigo='GESTAO' ON CONFLICT(codigo) DO UPDATE SET ativo=TRUE;
INSERT INTO menus(modulo_id,codigo,nome,rota,icone,ordem) SELECT id,'GESTAO_FONTES_DADOS','Fontes de Dados','/gestao/fontes-dados','Database',3 FROM modulos WHERE codigo='GESTAO' ON CONFLICT(codigo) DO UPDATE SET ativo=TRUE;
INSERT INTO telas(modulo_id,menu_id,codigo,nome,rota,arquivo_fonte,componentes_principais,endpoints_usados,tabelas_principais) SELECT m.id,me.id,'GESTAO_FLUXO_CAIXA','Fluxo de Caixa Premium','/gestao/fluxo-caixa','src/modulos/gestao/Gestao.tsx','Filtros, cards, calendário, tendência, grade e detalhes','/gestao/fluxo-caixa','gestao_fluxo_processo,gestao_fluxo_dia,gestao_fluxo_detalhe' FROM modulos m JOIN menus me ON me.codigo='GESTAO_FLUXO_CAIXA' WHERE m.codigo='GESTAO' ON CONFLICT(codigo) DO UPDATE SET ativo=TRUE;
INSERT INTO acoes(codigo,nome,descricao) VALUES ('gestao.acessar','Acessar Control S Gestão','Exibe o módulo'),('gestao.fluxo_caixa.visualizar','Visualizar fluxo de caixa','Consulta resultados'),('gestao.fluxo_caixa.processar','Processar fluxo de caixa','Executa fontes Oracle'),('gestao.fluxo_caixa.exportar_excel','Exportar fluxo em Excel','Gera arquivo Excel'),('gestao.fluxo_caixa.ver_detalhe','Ver documentos do fluxo','Exibe drill-down'),('gestao.fluxo_caixa.ver_insights','Ver insights','Exibe alertas automáticos'),('gestao.fluxo_caixa.configurar','Configurar fluxo','Edita regras'),('gestao.fonte_dados.visualizar','Visualizar fontes','Lista fontes SQL'),('gestao.fonte_dados.editar','Editar fontes','Altera SQL'),('gestao.fonte_dados.executar','Testar fontes','Executa consulta de teste'),('gestao.fonte_dados.ver_sql','Ver SQL','Exibe conteúdo SQL'),('gestao.fonte_dados.publicar','Publicar fontes','Publica versão'),('gestao.grupo_filial.visualizar','Visualizar grupos','Lista grupos de filiais'),('gestao.grupo_filial.editar','Editar grupos','Altera grupos de filiais') ON CONFLICT(codigo) DO NOTHING;
COMMIT;
